import{_ as e,o as a,c as o,a2 as s}from"./chunks/framework.CfwCq2QB.js";const i="/dev-go-docs/shots/0.2.3/en/light/sidepanel.png",n="/dev-go-docs/shots/0.2.3/en/dark/sidepanel.png",m=JSON.parse('{"title":"AI assistant","description":"","frontmatter":{},"headers":[],"relativePath":"en/features/assistant.md","filePath":"en/features/assistant.md"}'),r={name:"en/features/assistant.md"};function l(d,t,h,c,u,p){return a(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="ai-assistant" tabindex="-1">AI assistant <a class="header-anchor" href="#ai-assistant" aria-label="Permalink to &quot;AI assistant&quot;">​</a></h1><p>In one line: a side panel AI assistant (<code>Alt+2</code> to open / close) that summarizes the page, extracts key points, and answers questions about it — it reads the page content itself. &quot;Ask AI&quot; from the selection toolbar brings your selection here too.</p><h2 id="opening-it" tabindex="-1">Opening it <a class="header-anchor" href="#opening-it" aria-label="Permalink to &quot;Opening it&quot;">​</a></h2><ul><li>Shortcut <code>Alt+2</code> (<code>⌥2</code> on macOS); press again to close</li><li>Popup&#39;s Features page → AI assistant → &quot;Open&quot;</li><li>Floating dock → &quot;AI assistant&quot; or &quot;AI summary&quot;</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>Alt+2</code> is Chrome-only; Firefox controls side panels itself — open it from the popup or the floating dock there.</p></div><h2 id="quick-actions" tabindex="-1">Quick actions <a class="header-anchor" href="#quick-actions" aria-label="Permalink to &quot;Quick actions&quot;">​</a></h2><p>Three quick actions sit at the top of the panel, each preloaded with the current page:</p><table tabindex="0"><thead><tr><th>Action</th><th>What it does</th></tr></thead><tbody><tr><td>Summarize this page</td><td>One- or two-sentence overview, then the key points</td></tr><tr><td>Key points</td><td>Conclusions, data, steps, caveats — as a list</td></tr><tr><td>Explain this page</td><td>What the page is about, who it&#39;s for, what&#39;s worth attention</td></tr></tbody></table><h2 id="chatting" tabindex="-1">Chatting <a class="header-anchor" href="#chatting" aria-label="Permalink to &quot;Chatting&quot;">​</a></h2><ul><li>The assistant reads the current page&#39;s content itself (including Shadow DOM pages) — no copy-pasting</li><li>Answers stream in; expand <strong>reasoning</strong> to see the thinking</li><li>&quot;Ask AI&quot; from the selection toolbar brings the selection in as a quote; remove it above the input box</li><li>When the page provides WebMCP tools, or you&#39;ve added <a href="/dev-go-docs/en/features/site-tools.html">site tools</a> for the site, the AI can call them and act on the page (see <a href="/dev-go-docs/en/features/webmcp.html">Page tools</a>); runs show up as cards in the conversation</li><li>Say &quot;make a search tool for this site&quot; and the AI inspects the page, test-runs, and builds a site tool for you</li><li>Answers render Markdown: headings, lists, code blocks, tables and more</li></ul><p>Input box: <code>Enter</code> to send, <code>Shift + Enter</code> for a newline; click &quot;Stop&quot; while generating.</p><img src="'+i+'" alt="Side panel AI assistant" style="width:40%;display:block;margin-left:auto;margin-right:auto;"><p><em>The side panel assistant: quick actions on top, chat about the current page below.</em></p><img src="'+n+'" alt="Side panel in dark theme" style="width:40%;display:block;margin-left:auto;margin-right:auto;"><p><em>The side panel in dark theme.</em></p><h2 id="model-configuration" tabindex="-1">Model configuration <a class="header-anchor" href="#model-configuration" aria-label="Permalink to &quot;Model configuration&quot;">​</a></h2><p>The assistant uses the <a href="/dev-go-docs/en/settings/models.html">chat model</a> (configured separately from the translation model) — pick a strong model with tool calling. &quot;Settings&quot; at the top right of the panel jumps to the config, where you can also append custom instructions (e.g. &quot;keep answers short&quot;).</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Without a model, the input box says &quot;Configure a chat model in settings first&quot;</li><li>Browser built-in pages (<code>chrome://</code> URLs) can&#39;t be read; pages opened before DevGo was installed or updated are handled automatically, no refresh needed</li></ul>',19)])])}const f=e(r,[["render",l]]);export{m as __pageData,f as default};
